# Analyze gray demo transform around red (11,6), 0-index
orig={(11,7),(12,6),(12,7),(13,8)}
out={(9,4),(10,4),(10,5),(11,5),(11,7),(12,5),(12,7),(13,8)}
funcs={'id':lambda r,c:(r,c),'v':lambda r,c:(r,-c),'h':lambda r,c:(-r,c),'rot':lambda r,c:(-r,-c),'diag':lambda r,c:(c,r),'anti':lambda r,c:(-c,-r),'r90':lambda r,c:(c,-r),'r270':lambda r,c:(-c,r)}
for n,f in funcs.items():
    new={(11+f(r-11,c-6)[0],6+f(r-11,c-6)[1]) for r,c in orig}
    print(n,new, new|orig==out)
